-- Seed file to populate the database with SkillClub starting data
-- Run AFTER applying all migrations in supabase/migrations/.
-- All demo users share the password: skillclub2025
-- Requires pgcrypto extension (enabled by default in Supabase).

ON CONFLICT (id) DO NOTHING;

ON CONFLICT (id) DO UPDATE SET
  first_name = EXCLUDED.first_name,
  last_name = EXCLUDED.last_name,
  avatar_url = EXCLUDED.avatar_url,
  bio = EXCLUDED.bio,
  neighborhood = EXCLUDED.neighborhood,
  location = EXCLUDED.location,
  city = EXCLUDED.city,
  trust_tier = EXCLUDED.trust_tier,
  trust_score = EXCLUDED.trust_score,
  archetype = EXCLUDED.archetype,
  what_i_teach = EXCLUDED.what_i_teach,
  what_i_learn = EXCLUDED.what_i_learn,
  languages = EXCLUDED.languages,
  sessions_completed = EXCLUDED.sessions_completed,
  joined_at = EXCLUDED.joined_at;

ON CONFLICT (id) DO UPDATE SET
  title = EXCLUDED.title,
  description = EXCLUDED.description,
  avg_rating = EXCLUDED.avg_rating,
  reviews_count = EXCLUDED.reviews_count,
  who_for = EXCLUDED.who_for,
  what_session_looks_like = EXCLUDED.what_session_looks_like,
  location = EXCLUDED.location;

ON CONFLICT (id) DO NOTHING;
