INSERT INTO profiles (id, first_name, last_name, avatar_url, bio, neighborhood, location, city, trust_tier, trust_score, archetype, what_i_teach, what_i_learn, languages, sessions_completed, joined_at)
VALUES
('d866a014-436f-4055-aff5-e51efae24dc1', 'Yasmine', 'Benali', 'https://images.unsplash.com/photo-1531746020798-e6953c6e8e04?w=200&h=200&fit=crop&crop=face', 'Musician, language enthusiast, and lifelong learner. I teach classical piano and help people fall in love with French.', 'Guéliz', 'Guéliz, Marrakesh', 'Marrakesh', 3, 4.8, 'mixed', ARRAY['Classical Piano', 'French Conversation', 'Music Theory'], ARRAY['Watercolor Painting', 'Arabic Calligraphy'], ARRAY['Arabic', 'French', 'English'], 34, '2025-11-15T10:00:00Z'),
('a937c050-482f-48e0-bb82-cf8a4ca33e9b', 'Karim', 'Ouazzani', 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=200&h=200&fit=crop&crop=face', 'Software engineer by day, passionate home cook by night. Originally from Fès, living in Marrakesh for 5 years. I teach Python and Moroccan cuisine.', 'Hivernage', 'Hivernage, Marrakesh', 'Marrakesh', 3, 4.9, 'giver', ARRAY['Python Programming', 'Moroccan Cooking', 'Data Analysis'], ARRAY['Guitar', 'Spanish'], ARRAY['Arabic', 'French', 'English'], 67, '2025-10-01T10:00:00Z'),
('19d08e9d-c2bb-498c-84ed-4f7f25091d09', 'Layla', 'Tachfine', 'https://images.unsplash.com/photo-1494790108755-2616b332c24c?w=200&h=200&fit=crop&crop=face', 'Yoga instructor and mindfulness teacher. I believe in growing through movement and stillness alike.', 'Palmeraie', 'Palmeraie, Marrakesh', 'Marrakesh', 4, 4.95, 'connector', ARRAY['Vinyasa Yoga', 'Meditation', 'Breathwork'], ARRAY['Piano', 'Aquarelle Painting'], ARRAY['Arabic', 'French', 'English', 'Tamasheq'], 112, '2025-09-20T10:00:00Z'),
('4a9fbae7-10c0-406e-bacd-01f2ac4bd081', 'Omar', 'Chraibi', 'https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?w=200&h=200&fit=crop&crop=face', 'Retired architecture professor turned amateur chef. Spent 30 years teaching space — now teaching bread.', 'Medina', 'Medina, Marrakesh', 'Marrakesh', 3, 4.7, 'giver', ARRAY['Artisan Bread Making', 'Traditional Moroccan Pastry', 'Architecture Drawing'], ARRAY['Photography', 'Modern Painting'], ARRAY['Arabic', 'French'], 22, '2025-12-01T10:00:00Z'),
('e09cfeb6-5999-4c13-a4e9-0639d494bdde', 'Sofia', 'Ramos', 'https://images.unsplash.com/photo-1487412720507-e7ab37603c6f?w=200&h=200&fit=crop&crop=face', 'Spanish expat, passionate about flamenco guitar and bringing people together. I organize weekly music nights at Café Atlas.', 'Guéliz', 'Guéliz, Marrakesh', 'Marrakesh', 4, 4.85, 'connector', ARRAY['Flamenco Guitar', 'Spanish Language'], ARRAY['Oud', 'Darija (Moroccan Arabic)'], ARRAY['Spanish', 'French', 'English'], 48, '2025-10-15T10:00:00Z'),
('a4a11c1d-6202-4fc4-bbba-c90a1923e100', 'Adam', 'El Fassi', 'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?w=200&h=200&fit=crop&crop=face', 'Photographer with a 35mm heart. I teach street photography and the art of seeing light. All sessions happen outside.', 'Mellah', 'Mellah, Marrakesh', 'Marrakesh', 3, 4.6, 'giver', ARRAY['Film Photography', 'Street Photography', 'Darkroom Development'], ARRAY['Bookbinding', 'Screenprinting'], ARRAY['Arabic', 'French', 'English'], 29, '2026-01-10T10:00:00Z'),
('b9a13a82-3dcf-4e11-8557-4b726054ba9b', 'Inès', 'Morel', 'https://images.unsplash.com/photo-1544005313-94ddf0286df2?w=200&h=200&fit=crop&crop=face', 'French illustrator and watercolor artist living in Marrakesh. I teach drawing as a form of meditation.', 'Kasbah', 'Kasbah, Marrakesh', 'Marrakesh', 3, 4.75, 'giver', ARRAY['Watercolor Painting', 'Urban Sketching', 'Botanical Illustration'], ARRAY['Portuguese', 'Ceramics'], ARRAY['French', 'English'], 41, '2025-11-28T10:00:00Z'),
('1c60fcbb-ab5c-43f1-b8ae-24ecb9541a7d', 'Hassan', 'Aouzal', 'https://images.unsplash.com/photo-1558618666-fcd25c85cd64?w=200&h=200&fit=crop&crop=face', 'Competitive chess player, Oud musician, and new member of SKILLCLUB. Excited to share what I know.', 'Gueliz', 'Gueliz, Marrakesh', 'Marrakesh', 1, 0, 'seeker', ARRAY['Chess Strategy', 'Oud Fundamentals'], ARRAY['Python', 'Photography', 'Bread Making'], ARRAY['Arabic', 'French'], 0, '2026-03-10T10:00:00Z')
INSERT INTO skills (id, slug, teacher_id, title, category, description, philosophy, price_per_hour, format, languages, level, is_active, tags, cover_gradient, created_at, avg_rating, reviews_count, currency, who_for, what_session_looks_like, location)
VALUES
('f782c5e5-3977-49ac-ab0e-4cd812674e2a', 'classical-piano-yasmine-benali', 'd866a014-436f-4055-aff5-e51efae24dc1', 'Classical Piano', 'music', 'Piano is not just about playing notes — it is about learning to listen. In our sessions together, you will discover the emotional language of music through the classical repertoire: Bach, Chopin, Debussy. Whether you have never touched a piano or you played as a child and want to return, this is for you.', 'I believe that technique exists to serve feeling. Before we work on scales, we work on listening. I want you to hear music differently after our first session.', 250, 'both', ARRAY['French', 'English', 'Arabic'], 'all levels', true, ARRAY['beginner-friendly', 'patient teacher', 'adults welcome', 'emotional approach'], 'from-plum-pale to-purple-100', '2025-11-20T10:00:00Z', 4.9, 18, 'MAD', 'Perfect for beginners and intermediate students who want to reconnect with music. Also wonderful for adults who are learning for the first time at any age.', 'We start with 10 minutes of active listening — I play something, you describe what you hear and feel. Then 30–40 minutes of technique and pieces. We end with you playing something complete, no matter how simple.', 'Guéliz, Marrakesh (my studio)'),
('26debc56-3c0f-4888-bc04-890cc4d9f67a', 'python-programming-karim-ouazzani', 'a937c050-482f-48e0-bb82-cf8a4ca33e9b', 'Python Programming', 'technology', 'I teach Python the way I wish someone had taught me — by building things you actually care about. Forget boring exercises. We will build a tool that automates something annoying in your life within the first two sessions.', 'Code should solve real problems. Every skill I teach, you will use the next week.', 300, 'both', ARRAY['French', 'English', 'Arabic'], 'beginner', true, ARRAY['project-based', 'beginner-friendly', 'practical', 'flexible schedule'], 'from-blue-50 to-indigo-100', '2025-10-05T10:00:00Z', 4.9, 31, 'MAD', 'Complete beginners who have been wanting to learn but felt overwhelmed. Also professionals in non-tech fields (accountants, doctors, teachers) who want to use data better.', 'First session: we understand your goal. What do you want to build? Then we start immediately. No theory without application.', 'Hivernage, Marrakesh / Online'),
('f157ad93-87a1-43e8-8db9-8bf178d227e8', 'moroccan-cooking-karim-ouazzani', 'a937c050-482f-48e0-bb82-cf8a4ca33e9b', 'Moroccan Home Cooking', 'cooking', 'The real Moroccan kitchen is not a restaurant kitchen — it is slower, more generous, full of stories. I teach you to cook the way my mother taught me: without a written recipe, by smell and touch and taste. Tagines, couscous, pastilla, harira.', 'A recipe is just a memory. Once you understand why each spice goes in and when, you can cook anything.', 200, 'in-person', ARRAY['Arabic', 'French', 'English'], 'all levels', true, ARRAY['hands-on', 'cultural experience', 'market visit', 'group sessions available'], 'from-amber-50 to-orange-100', '2025-10-10T10:00:00Z', 4.95, 15, 'MAD', 'Anyone who loves food. Especially good for expats living in Morocco who want to cook locally, and for Moroccan diaspora who want to reconnect with home flavors.', 'We shop together at the souk or I bring ingredients. We cook together for 2 hours. We eat what we make. We talk.', 'Hivernage, Marrakesh'),
('d61394a1-b4f7-41a4-9e32-a5e227fc66cc', 'vinyasa-yoga-layla-tachfine', '19d08e9d-c2bb-498c-84ed-4f7f25091d09', 'Vinyasa Yoga & Meditation', 'fitness', 'Not just a workout — a practice for living. My sessions combine movement, breath, and stillness to help you feel more present in your body and life. We meet in the palm garden or on rooftop terraces.', 'The body knows what the mind has forgotten. I help you listen again.', 180, 'in-person', ARRAY['English', 'French', 'Arabic'], 'all levels', true, ARRAY['outdoor sessions', 'all levels', 'mindfulness', 'beginner-friendly'], 'from-forest-pale to-green-50', '2025-09-25T10:00:00Z', 4.95, 47, 'MAD', 'All bodies and fitness levels. Especially transformative for people going through a transition — new to the city, changing careers, new parents.', '75 minutes: 10 min centering, 50 min moving practice, 15 min meditation and integration. Always outside when weather permits.', 'Palmeraie, Marrakesh (outdoor)'),
('e06cbe8a-ebd0-45eb-89a1-cb0b628ec26f', 'artisan-bread-omar-chraibi', '4a9fbae7-10c0-406e-bacd-01f2ac4bd081', 'Artisan Bread Making', 'cooking', 'The oldest craft still practiced daily in medinas across Morocco. I teach you the science of fermentation, the art of shaping, and the patience of waiting. We make sourdough, khobz, msemen, and batbout.', 'Bread is the most honest thing you can make. It tells you exactly what you gave it.', 150, 'in-person', ARRAY['Arabic', 'French'], 'all levels', true, ARRAY['morning sessions', 'hands-on', 'takes half a day', 'max 3 students'], 'from-yellow-50 to-amber-100', '2025-12-05T10:00:00Z', 4.7, 11, 'MAD', 'Anyone who has ever wanted to make bread from scratch. No experience necessary — only curiosity.', 'Morning sessions (bread needs a whole morning). We begin at 8am, start the levain, shape, wait, bake, and eat together around noon.', 'Medina, Marrakesh'),
('6320a402-9a3d-4c31-9ff7-377bb459a997', 'flamenco-guitar-sofia-ramos', 'e09cfeb6-5999-4c13-a4e9-0639d494bdde', 'Flamenco Guitar', 'music', 'Flamenco is not learned — it is felt. I start with the rhythmic foundation (compás), because without rhythm guitar is just sound. But I promise you, within three sessions you will play something that makes your spine tingle.', 'Duende — that electricity that makes your hair stand up. That is what we are chasing.', 280, 'both', ARRAY['Spanish', 'French', 'English'], 'beginner', true, ARRAY['cultural immersion', 'rhythm-first', 'passionate teacher', 'small groups welcome'], 'from-red-50 to-rose-100', '2025-10-20T10:00:00Z', 4.85, 22, 'MAD', 'Guitar players with at least some basic knowledge. Also absolute beginners with a high tolerance for obsession.', '30 min on compás exercises, 30 min learning a specific form (soleares, bulerías, rumba), 30 min play-together improvisation.', 'Guéliz, Marrakesh'),
('bbaaa84a-500b-42af-97d8-15cf64d370b3', 'film-photography-adam-el-fassi', 'a4a11c1d-6202-4fc4-bbba-c90a1923e100', 'Film Photography', 'photography', 'We slow down. We use a camera with 36 frames. We go out into the city and we learn to see. Film photography teaches you what digital cannot: patience, consequence, and the value of a single frame.', 'Every photo you take costs something. That changes how you see.', 200, 'in-person', ARRAY['Arabic', 'French', 'English'], 'all levels', true, ARRAY['outdoor sessions', 'includes film cost', 'darkroom access', 'small groups'], 'from-gray-100 to-slate-100', '2026-01-15T10:00:00Z', 4.6, 14, 'MAD', 'People who love photography but feel their digital work is getting worse, not better. Also perfect beginners who want to start with purpose.', 'We meet with a loaded camera. We walk the Medina or Mellah for 2 hours. I explain settings, light, composition in the moment — not in a classroom. We develop the film in my small darkroom.', 'Medina / Mellah, Marrakesh'),
('765f0e37-f4e9-4672-9cc9-5a828cb0f1dc', 'watercolor-painting-ines-morel', 'b9a13a82-3dcf-4e11-8557-4b726054ba9b', 'Watercolor Painting', 'art', 'Watercolor is the most forgiving medium and the most honest. It does what it wants. My sessions teach you to work with its nature, not against it — to embrace happy accidents and learn to see color as light.', 'You cannot control watercolor. You can only learn to dance with it.', 220, 'both', ARRAY['French', 'English'], 'beginner', true, ARRAY['all materials provided', 'slow pace', 'therapeutic', 'small groups max 4'], 'from-violet-50 to-purple-50', '2025-12-01T10:00:00Z', 4.75, 19, 'MAD', 'Absolute beginners are very welcome. Also for people who tried watercolor before and got frustrated — I specialise in rebuilding that relationship.', '2-hour session: 20 min of warm-up exercises (color mixing, wet-on-wet), then 90 min working on a specific subject or technique. We often work from life — gardens, riads, markets.', 'Kasbah, Marrakesh')
INSERT INTO reviews (id, skill_id, reviewer_id, rating, content, tags, created_at)
VALUES
('c830ddaf-ab3c-4cf7-80be-8e1c662985f4', 'f782c5e5-3977-49ac-ab0e-4cd812674e2a', 'e09cfeb6-5999-4c13-a4e9-0639d494bdde', 5, 'Yasmine does something I have never experienced with a music teacher — she makes you feel the music before she teaches you to play it. After one session I cried. Not from difficulty but from beauty. I understood for the first time what music is for.', ARRAY['Emotionally intelligent', 'Patient', 'Changed my perspective'], '2025-12-15T14:00:00Z'),
('ad9e28f3-e522-4a0b-99d8-c1fefbf6b761', 'f782c5e5-3977-49ac-ab0e-4cd812674e2a', '4a9fbae7-10c0-406e-bacd-01f2ac4bd081', 5, 'I am 67 years old. I always wanted to play piano and always thought I was too old. Yasmine proved me wrong in the first ten minutes. She is a gift.', ARRAY['Adults welcome', 'Encouraging', 'Patient'], '2026-01-20T10:00:00Z'),
('bf9d3326-dc8d-4a37-b9f1-a832c6b412bf', '26debc56-3c0f-4888-bc04-890cc4d9f67a', 'b9a13a82-3dcf-4e11-8557-4b726054ba9b', 5, 'Within 4 sessions with Karim I built a script that saves me 3 hours every week. He is a brilliant teacher because he cares deeply about what you actually need, not about impressing you with his own knowledge.', ARRAY['Practical', 'Goal-oriented', 'Patient with beginners'], '2026-01-05T10:00:00Z'),
('f13bf3a5-ee89-4bc2-af83-9ece80a84f37', 'f157ad93-87a1-43e8-8db9-8bf178d227e8', 'd866a014-436f-4055-aff5-e51efae24dc1', 5, 'I came to Marrakesh from Paris three years ago. I have been eating tagine in restaurants ever since. After one session with Karim, I made better tagine in my own kitchen than any I have eaten here. The souk visit alone was worth it.', ARRAY['Cultural depth', 'Hands-on', 'Memorable experience'], '2026-02-10T09:00:00Z'),
('c201d4a0-53bc-40d1-b541-dbcf156feab6', 'd61394a1-b4f7-41a4-9e32-a5e227fc66cc', 'a4a11c1d-6202-4fc4-bbba-c90a1923e100', 5, 'Layla is not just a yoga teacher — she is a presence. The session in the palm garden at sunrise was one of the most beautiful experiences I have had in Marrakesh. Do not miss this.', ARRAY['Transcendent', 'Outdoor magic', 'All levels truly welcome'], '2025-12-20T07:00:00Z')
